body {
  font-family: "Literata", Georgia, serif;
  font-size: 1.125rem;
  line-height: 1.6;
  color: #17202b;
  background: #edf0ee;
}

h1 {
  font-size: clamp(2.2rem, 1.5rem + 3vw, 3.4rem);
  letter-spacing: -0.02em;
}

* , *::before, *::after {
  box-sizing: border-box;
}

.carte {
  width: 320px;
  padding: 16px;
  border: 1px solid #ccd3da;
  margin-bottom: 24px;
}

.barre {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.barre .logo {
  margin-right: auto;
}

